const {execFileSync} = require('child_process');
const fs = require('fs');
const EXE='/workspace/dataset/test13_executable';
const OUT='/workspace/probes/draft201909-202012.jsonl';
function run(a,b){
  let out='', code=0;
  try{ out=execFileSync(EXE,['--a',a,'--b',b],{encoding:'utf8',stdio:['ignore','pipe','ignore']}); }
  catch(e){ out=(e.stdout||''); code=(e.status===null||e.status===undefined)?-1:e.status; }
  fs.appendFileSync(OUT, JSON.stringify({a:a,b:b,out:out,exit:code})+'\n');
  return {out,code};
}
module.exports={run};
if(require.main===module){
  const pairs=JSON.parse(fs.readFileSync(process.argv[2],'utf8'));
  for(const [a,b] of pairs){
    const r=run(a,b);
    console.log(JSON.stringify(b).slice(0,150),'||',JSON.stringify(a).slice(0,60),'=>',r.out.trim().replace(/\n/g,' '),'exit',r.code);
  }
}
EOF
